import Foundation

/// Destinations are working experiment benches, not promises of a complete course.
enum LabDestination: String, CaseIterable, Identifiable {
    case circuits, logic, transient, ac, semiconductor, signals, control, fields, communications, power

    var id: String { rawValue }

    var title: String {
        switch self {
        case .circuits: "DC circuits"
        case .logic: "Logic boards"
        case .transient: "Time & storage"
        case .ac: "AC & impedance"
        case .semiconductor: "Devices & amplifiers"
        case .signals: "Signals & sampling"
        case .control: "Feedback"
        case .fields: "Fields & potential"
        case .communications: "Modulation"
        case .power: "Power & phase"
        }
    }

    var symbol: String {
        switch self {
        case .circuits: "bolt.horizontal.circle"
        case .logic: "cpu"
        case .transient: "clock.arrow.circlepath"
        case .ac: "waveform.path"
        case .semiconductor: "triangle"
        case .signals: "waveform"
        case .control: "arrow.trianglehead.2.clockwise.rotate.90"
        case .fields: "dot.radiowaves.left.and.right"
        case .communications: "antenna.radiowaves.left.and.right"
        case .power: "bolt.circle"
        }
    }
}

struct CourseModule: Identifiable {
    let id: String
    let title: String
    let subtitle: String
    let symbol: String
    let stage: Int
    let lessons: [CourseLesson]
    let prerequisites: [String]

    var implementedCount: Int { lessons.filter(\.isImplemented).count }
}

struct CourseLesson: Identifiable {
    let id: String
    let title: String
    let concept: String
    let equation: String
    let experiment: String
    let challenge: String
    let modelLimit: String
    let destination: LabDestination?
    var advancedExperiment: AdvancedLessonID? { AdvancedLessonID(rawValue: id) }
    var isImplemented: Bool { destination != nil || advancedExperiment != nil }
}

struct CurriculumSource: Identifiable {
    let title: String
    let url: String
    var id: String { url }
}

enum Curriculum {
    static let scopeStatement = "54 interactive lessons across an EE curriculum: mathematics, circuits, devices, signals, control, fields, communications, power, computing and engineering practice. Each experiment names its assumptions. This app does not award a degree or replace physical laboratory evidence."
    static let fidelityStatement = "Every bench names its physical model and assumptions. Results follow that model; idealizations and numerical approximations stay visible."

    static let sources: [CurriculumSource] = [
        .init(title: "ABET engineering criteria · 2026–2027", url: "https://www.abet.org/accreditation/accreditation-criteria/criteria-for-accrediting-engineering-programs-2026-2027/"),
        .init(title: "Illinois · Electrical Engineering BS", url: "https://catalog.illinois.edu/undergraduate/engineering/electrical-engineering-bs/"),
        .init(title: "MIT · Electrical Engineering with Computing", url: "https://catalog.mit.edu/degree-charts/electrical-engineering-computing-course-6-5/"),
        .init(title: "MIT · EECS specialization tracks", url: "https://catalog.mit.edu/degree-charts/electrical-engineering-computer-science-tracks/")
    ]

    static let modules: [CourseModule] = [
        .init(id: "foundations", title: "The language of electricity", subtitle: "Units, mathematics, physics & uncertainty", symbol: "function", stage: 1, lessons: [
            live("units", "Charge, current, voltage & energy", "Charge is conserved. Current measures charge flow; voltage measures energy transferred per unit charge. Choose a reference and a sign convention before calculating.", "Constant DC: Q = IΔt · W = VIΔt · 1 A = 1 C/s · 1 V = 1 J/C · 1 W = 1 J/s", "Adjust source voltage, resistance and the DC accounting interval; select a component and compare its signed charge and energy.", "Double the accounting interval while keeping the circuit unchanged; predict how Q and W change.", "Ideal constant-DC integration with signed current a → b and passive power convention. Negative energy means supplied energy; no time-varying waveform integration or microscopic transport.", .circuits),
            interactive("calculus", "Calculus: accumulation & change", "A derivative measures local change. An integral accumulates it. These two operations connect current to charge and power to energy.", "Q(t) − Q(0) = ∫₀ᵗ i(τ)dτ", "Vary a sinusoidal or ramp current, inspect the selected time, and compare accumulated charge with instantaneous current.", "Find two different current waveforms that transfer the same total charge.", "Specified sine/ramp functions with analytical integration and derivative. No symbolic integration engine or arbitrary drawn waveforms."),
            interactive("linear-algebra", "Vectors, matrices & complex numbers", "Kirchhoff equations become a linear system. Complex numbers encode sinusoid amplitude and phase; vectors also describe fields in space.", "Ax = b · eʲθ = cos θ + j sin θ", "Change a grounded two-node network source and resistances, inspect its conductance matrix and node voltages, then rotate an RC phasor.", "Identify what a singular circuit matrix says about an unreferenced node.", "A specified grounded two-node resistive network with positive resistances and an ideal unloaded RC phasor. No arbitrary matrix editor, current-injection topology or symbolic proof engine."),
            interactive("differential-equations", "Differential equations & initial conditions", "Stored energy makes future behavior depend on present state. A differential equation and initial conditions determine an ideal model's trajectory.", "τ dx/dt + x = u(t)", "Set a first-order state, input, time constant and timestep; compare exact, forward-Euler and backward-Euler trajectories.", "Predict which initial condition changes a transient without changing its final value.", "Scalar constant-input linear ODE with an explicit initial condition. Euler curves have timestep error; forward Euler can be unstable. No arbitrary nonlinear ODE solver."),
            interactive("probability", "Probability, statistics & measurement", "A measurement has uncertainty. Probability models variation; statistics estimates parameters from data and distinguishes repeatability from bias.", "E[X] = Σx p(x) · Var(X) = E[(X − μ)²]", "Change independent sample count and a bounded uniform resistor tolerance; compare sample statistics with exact current-distribution expectations.", "Explain why averaging repeated measurements does not remove a fixed calibration error.", "Named uniform resistance distribution and deterministic repeatable samples, with exact transformed-current moments. Statistical estimates describe this model; averaging does not remove fixed bias."),
            interactive("matter", "Mechanics, thermal physics & matter", "Energy links electrical work to motion and heat. Material structure and quantum states explain why conductors, insulators and semiconductors behave differently.", "W = ∫F·dx · ΔU = Q − W · E = hf", "Explore conductivity and Joule heating, mechanical work and photon energy using bounded material and energy parameters.", "Describe where resistor heat comes from without treating resistance as charge consumption.", "Ohmic uniform material, lumped constant heat capacity, constant-force work and E=hf photon energy. No microscopic band-structure, chemistry, quantum many-body or spatial thermal solver.")
        ], prerequisites: []),

        .init(id: "circuits", title: "Circuits from conservation", subtitle: "Ohm, Kirchhoff & equivalent networks", symbol: "bolt.horizontal.circle", stage: 1, lessons: [
            live("ohm", "Voltage pushes; resistance sets current", "For an ideal resistor, voltage and current are proportional. Doubling resistance at fixed voltage halves current; electrical power becomes heat in a real resistor.", "V = IR · P = VI = I²R", "Change source voltage and resistance in a DC preset; compare the current readout.", "Choose resistance for 5 V and 1 mA, then check the result.", "Ideal linear resistor and ideal DC source; no temperature drift, wire resistance or rated-power failure.", .circuits),
            live("series", "Series: one path for current", "Components on an unbranched path carry the same current. Their voltage drops add to the source voltage.", "Rₑq = ΣRₖ · ΣVₖ = Vₛ", "Use the series preset and change one resistance while watching all voltage drops.", "Make one resistor dissipate twice the other's power at the same series current.", "Steady-state lumped resistors; source and connecting wires are ideal.", .circuits),
            live("parallel", "Parallel: shared voltage, split current", "Branches connected to the same two nodes share voltage. Branch conductance determines how much current each takes.", "1/Rₑq = 1/R₁ + 1/R₂ · Iₛ = I₁ + I₂", "Use the parallel preset; vary a branch resistor and observe total and branch current.", "Start with a single resistor, then add an identical parallel branch. Explain why source current doubles.", "Ideal grounded DC network; parasitic resistance and source current limits are absent.", .circuits),
            live("kirchhoff", "Kirchhoff: account for every junction", "Charge conservation makes signed currents at a node sum to zero. Around a closed loop, signed voltage changes sum to zero within a lumped circuit model.", "ΣI_node = 0 · ΣV_loop = 0", "Inspect the DC branch readouts and add currents at a junction by their reference directions.", "Check both current balance and loop voltage balance for the divider preset.", "Lumped, steady-state circuit approximation; changing magnetic flux is outside the DC model.", .circuits),
            live("divider", "A voltage divider is a ratio", "Two series resistors divide a source voltage. Loading the output changes the effective lower resistance and therefore the output voltage.", "Unloaded: V_out = Vₛ R₂/(R₁ + R₂)", "Change the divider resistors; then add an output load and compare the node voltage.", "Find two resistance pairs giving half the source voltage but different current draw.", "Ideal DC resistor network. The simple ratio assumes an unloaded output; a load must be included in the solved network.", .circuits)
        ], prerequisites: ["foundations"]),

        .init(id: "digital", title: "From bits to logic boards", subtitle: "Build on Flips: truth, arithmetic & memory", symbol: "cpu", stage: 1, lessons: [
            live("gates", "Logic gates implement propositions", "AND requires both inputs; OR needs either; NOT inverts. NAND, NOR, XOR and XNOR build further Boolean operations from the same two logical values.", "AND: Y = A·B · XOR: Y = A ⊕ B", "Choose a gate, toggle inputs and compare its output with the truth table.", "Distinguish OR from XOR using the input combination A = B = 1.", "Ideal digital abstraction; logic values are not analog voltages and there are no gate delays or electrical thresholds.", .logic),
            live("truth-tables", "Truth tables are complete experiments", "A two-input combinational gate has four binary input combinations. Checking every row establishes its Boolean behavior for those inputs.", "n inputs → 2ⁿ binary input combinations", "Exercise all four input pairs and read the selected gate's truth table.", "Find the controlling input value that fixes an AND or OR output.", "The interactive truth table covers the selected ideal gate; it does not prove a transistor implementation or timing behavior.", .logic),
            live("binary-addition", "Carries connect arithmetic to circuits", "A full adder combines two operand bits and an incoming carry. Chaining carry outputs forms a multi-bit unsigned adder, linking Flips' place values to gates.", "S = A ⊕ B ⊕ C_in · C_out = AB + C_in(A ⊕ B)", "Change the logic bench's operand bits and compare the sum with binary place values.", "Find an addition that carries through several bit positions and explain each carry.", "Ideal finite-width unsigned arithmetic; no propagation delay, transistor power, signed overflow analysis or physical layout.", .logic),
            interactive("sequential", "Sequential logic remembers", "A register stores state at a clock event. Combinational logic plus stored state forms counters, finite-state machines and synchronous systems.", "q[n + 1] = d[n] at the active clock edge", "Toggle data, clock a register, advance a binary counter and inspect a finite-state controller one event at a time.", "Explain why feedback alone is not the same as a clocked state machine.", "Ideal event-based logical register/counter/FSM. No transistor implementation, analog metastability or physical clock network."),
            interactive("digital-timing", "Timing, hazards & physical logic", "Real gates need time to respond. Setup, hold and propagation constraints determine whether a synchronous design captures the intended value.", "T_clk ≥ t_CQ,max + t_logic,max + t_setup − skew", "Move clock period, logic propagation delays and clock skew; inspect synchronous margins and a reconvergent-path hazard.", "Explain why a functionally correct truth table can still produce an unreliable circuit.", "Deterministic transport-delay hazard and synchronous timing constraints. Clock-to-Q/setup/hold requirements are fixed and disclosed; violations are flagged rather than rendered as exact analog metastability.")
        ], prerequisites: ["foundations"]),

        .init(id: "dynamics", title: "Energy gives circuits a memory", subtitle: "Capacitors, inductors, transients & AC", symbol: "waveform.path", stage: 2, lessons: [
            live("rc", "Capacitors charge over time", "A capacitor stores energy in an electric field. Through a resistor, its voltage approaches the source exponentially; RC sets the time scale.", "i_C = C dv_C/dt · τ = RC · v_C = Vₛ(1 − e^(−t/(RC)))", "Vary R and C in the RC charging bench; compare the analytical and numerical capacitor-voltage traces.", "Predict the voltage after one time constant and explain why it is about 63.2% of the final step.", "Ideal constant-source RC charging from zero voltage. Backward Euler has finite-timestep error; the analytical curve is exact for this model.", .transient),
            interactive("inductors", "Inductors resist a change in current", "An inductor stores energy in a magnetic field. Its voltage is proportional to current's rate of change; ideal inductor current cannot jump under finite voltage.", "v_L = L di_L/dt · W_L = ½Li_L² · τ_RL = L/R", "Change R, L and source voltage, energize or release the RL circuit, and inspect current and stored magnetic energy.", "Explain the voltage required to interrupt an inductor's current instantly.", "Ideal linear lumped RL with prescribed initial conditions. No core saturation, winding capacitance, flyback breakdown or wire inductance."),
            live("phasors", "An RC filter changes amplitude & phase", "In sinusoidal steady state, a resistor followed by a capacitor to ground forms a low-pass filter. Its capacitor output shrinks and lags as frequency rises.", "H(jω) = 1/(1 + jωRC) · f_c = 1/(2πRC)", "Change R, C and frequency; compare input/output waveforms, gain and phase in the RC low-pass bench.", "At cutoff, check the gain 1/√2 and phase −45°, then explain the capacitor's role.", "Ideal unloaded first-order RC low-pass in sinusoidal steady state; this bench is not a general AC network solver.", .ac),
            interactive("resonance", "Resonance trades electric and magnetic energy", "In an ideal series RLC network, inductive and capacitive reactance cancel at resonance. Resistance still determines current and dissipation.", "ω₀ = 1/√(LC) · Z = R + j(ωL − 1/(ωC))", "Sweep an ideal series RLC circuit through resonance and change resistance to compare damping, current and bandwidth.", "Explain why ideal resonance does not make series current infinite when R is nonzero.", "Series RLC with positive finite R/L/C. Energy exchange and frequency response follow lumped linear equations; no distributed resonance or frequency-dependent real component loss."),
            interactive("network-analysis", "Network methods & transforms", "Nodal and mesh methods generalize conservation equations. Equivalent-source models and Laplace transforms let us reason about loaded circuits and dynamics systematically.", "V_th = V_oc · I_N = V_th/R_th · L{dx/dt} = sX(s) − x(0)", "Derive a divider Thevenin source, connect a variable load, inspect delivered power, and relate an RC pole to its impulse response.", "State which source deactivation rule applies when finding an equivalent resistance.", "Linear resistor divider and ideal Thevenin equivalent, plus first-order RC Laplace transfer. Not a general dependent-source, mesh, two-port or symbolic-transform editor.")
        ], prerequisites: ["circuits", "foundations"]),

        .init(id: "devices", title: "Matter becomes electronics", subtitle: "Junctions, transistors & feedback amplifiers", symbol: "triangle", stage: 2, lessons: [
            live("diode", "A diode is not a fixed voltage drop", "A junction's current changes approximately exponentially with applied voltage in the Shockley model. Temperature, saturation current and ideality factor set the relationship.", "I = Iₛ(e^(V/(nV_T)) − 1) · V_T = kT/q", "Vary diode voltage, ideality factor and saturation current; inspect the I–V curve.", "Explain why a quoted 0.7 V is an operating approximation rather than a universal switch threshold.", "Shockley junction at 300 K; no breakdown, series resistance, self-heating, stored charge or current-rating failure.", .semiconductor),
            interactive("bjt", "Bipolar transistors & bias", "A bipolar transistor uses junction injection to control collector current. A circuit must establish a bias point before small changes can be amplified predictably.", "I_C ≈ I_S e^(V_BE/V_T) in forward-active operation", "Vary base-emitter and collector-emitter voltages; inspect reciprocal Ebers-Moll terminal currents, operating region and current balance.", "Explain why a current-gain number alone is insufficient to predict a transistor circuit.", "Low-injection reciprocal Ebers-Moll junction model with explicit terminal voltages and terminal KCL. No collector-load circuit, Early effect, charge storage, self-heating or full device parameter extraction."),
            interactive("mosfet", "MOSFETs: a field controls a channel", "A gate field changes channel conduction. Threshold, terminal voltages and geometry determine operating region; a MOSFET is not an ideal switch in all conditions.", "Long-channel saturation: I_D ≈ ½μC_ox(W/L)(V_GS − V_T)²", "Move gate and drain voltages across cutoff, triode and saturation; inspect drain current and transconductance.", "Distinguish threshold voltage from the gate voltage needed for a specified on-resistance.", "Ideal long-channel square-law MOSFET with specified threshold and geometry parameter. No subthreshold, body effect, short-channel, capacitance or switching-loss model."),
            live("opamp", "An inverting amplifier uses feedback", "Negative feedback in an ideal inverting amplifier fixes gain by a resistor ratio while the output remains within its supply rails.", "v_out = −(R_f/R_in)v_in, limited by output rails", "Change input voltage and resistor ratio; observe inverted gain and rail clipping.", "Predict when a requested gain forces the output against a supply rail.", "Ideal op-amp with hard symmetric rail limits; no bandwidth, slew rate, offset, input bias current or output-current limits.", .semiconductor),
            interactive("analog-design", "Small-signal models & analog design", "Linearizing near a bias point separates a circuit's operating condition from its response to small variations. Device capacitances and feedback limit gain and bandwidth.", "g_m = ∂I_C/∂V_BE at the bias point", "Change bias and input amplitude; compare a local transistor small-signal prediction against the nonlinear waveform and output headroom.", "Find an input amplitude where a linear approximation stops predicting the waveform accurately.", "Specified common-emitter stage linearized at a bias point. The nonlinear comparison exposes amplitude limits; not a general amplifier/noise/IC or oscillator design engine.")
        ], prerequisites: ["circuits", "dynamics", "foundations"]),

        .init(id: "signals", title: "Signals carry structure", subtitle: "Harmonics, sampling, transforms & DSP", symbol: "waveform", stage: 2, lessons: [
            live("harmonics", "Build a waveform from harmonics", "Sinusoids add by superposition. Changing the second and third harmonics reshapes a periodic waveform while each component remains tied to the fundamental frequency.", "x(t) = (1 V)sin(2πf₀t) + A₂sin(4πf₀t) + A₃sin(6πf₀t)", "Change fundamental frequency and the second/third harmonic amplitudes; observe the resulting waveform.", "Describe how adding an odd harmonic can sharpen the waveform without changing its period.", "Three sine components with fixed 1 V fundamental amplitude and fixed phases; second/third amplitudes are adjustable. No arbitrary waveform analyzer or audio input.", .signals),
            live("sampling", "Sampling can hide frequency", "Discrete samples cannot uniquely distinguish frequencies separated by integer multiples of sample rate. A bandlimited signal below half the sample rate can be reconstructed ideally.", "f_s > 2f_max for an ideally bandlimited signal", "Change sample rate and signal frequency; inspect sample markers and folded alias frequency.", "Find two different sine frequencies that produce the same discrete sample sequence.", "Ideal uniform point samples and an analytical alias fold; no ADC quantization, clock jitter or anti-alias filter simulation.", .signals),
            interactive("systems", "Systems, convolution & impulse response", "A linear time-invariant system is characterized by its impulse response. Convolution combines input and impulse response to produce output.", "y[n] = Σₖ x[k]h[n − k]", "Change a finite input pulse and decaying impulse-response taps; inspect one convolution sum and the complete output sequence.", "Explain which property fails if a system's behavior changes with absolute time.", "Finite discrete causal LTI convolution with zero padding and explicit sample indexing. Not continuous arbitrary-function convolution or a time-varying/nonlinear system model."),
            interactive("transforms", "Fourier, Laplace & z transforms", "Transforms change the representation of a signal or system. Frequency content, poles and zeros reveal behavior that can be difficult to see in a raw waveform.", "X(eʲω) = Σₙ x[n]e^(−jωn)", "Vary a sampled tone and choose a rectangular or Hann window; inspect a 64-point DFT spectrum and spectral leakage.", "Explain why frequency-bin spacing is different from the sample rate.", "Finite real sequence, direct DFT, explicit sample rate and window coherent-gain normalization. No infinite-time transform or complete Laplace/z-transform derivation is inferred."),
            interactive("dsp", "Design a digital filter", "A digital filter combines delayed samples with coefficients. Coefficient choice shapes frequency response; numerical precision and implementation affect practical behavior.", "FIR: y[n] = Σₖ bₖx[n − k]", "Edit three FIR taps; compare input/output tones, impulse response and the filter frequency response.", "Choose a filter that reduces high-frequency noise while preserving a slow signal.", "Causal three-tap real FIR with zero initial state and floating-point coefficients. No IIR synthesis, fixed-point quantization, multirate or hardware latency model.")
        ], prerequisites: ["foundations", "dynamics"]),

        .init(id: "control", title: "Feedback shapes behavior", subtitle: "Closed loops, stability & state", symbol: "arrow.triangle.2.circlepath", stage: 3, lessons: [
            live("feedback", "Proportional control closes the loop", "A controller compares a setpoint with the measured output. For this stable first-order plant, more proportional gain speeds the response and reduces steady-state error.", "G(s) = 1/(τs + 1) · T(s) = K_p/(τs + 1 + K_p)", "Change proportional gain Kₚ and plant time constant τ; inspect the unit-step response.", "Explain why finite proportional gain leaves a steady-state error in this model.", "Ideal stable first-order plant with unit DC gain, zero initial state and unity feedback; no saturation, delay, sensor noise or oscillatory dynamics.", .control),
            interactive("stability", "Poles, stability & frequency response", "For a continuous linear system, pole locations determine natural modes. Loop gain and phase must be assessed together before assuming that feedback improves behavior.", "Continuous asymptotic stability: Re(p_i) < 0", "Move a conjugate pole pair across the imaginary axis and inspect the corresponding exact second-order step response.", "Explain how delay can destabilize a loop even when its static feedback sign is negative.", "Specified real second-order transfer function with explicit pole placement. Marginal versus asymptotic stability is distinguished; no claim of general Nyquist, delay or high-order loop analysis."),
            interactive("pid", "Integral & derivative control", "Integral action accumulates error; derivative action responds to change. Both introduce design tradeoffs, including windup and sensitivity to noise.", "u = clamp(Kₚe + I − KᴅDᶠ[y]) · Dᶠ[y] = filtered measurement derivative", "Tune proportional, integral and derivative terms, add a load disturbance, and compare actuator saturation with conditional antiwindup.", "Describe why an integral controller needs a windup strategy when an actuator saturates.", "Sampled first-order plant/controller, held-input plant update, filtered derivative on measurement and defined actuator limits. Numerical timestep and disturbance assumptions remain explicit."),
            interactive("state-space", "State, estimation & optimal control", "A state summarizes the information needed to predict a dynamic system. State-space models support multi-input systems, observers and controlled tradeoffs.", "ẋ = Ax + Bu · y = Cx + Du", "Change control-effort penalty and observer rate; inspect a double-integrator LQR response and position-only state estimates.", "Distinguish an observable system from a controllable one.", "Specified observable double integrator, fixed state penalty Q=I and analytic continuous LQR gains with variable control penalty R; Luenberger observer with RK4 and deterministic sensor ripple. No general Kalman filter or arbitrary multi-input optimizer.")
        ], prerequisites: ["signals", "foundations"]),

        .init(id: "fields", title: "Circuits live inside fields", subtitle: "Electrostatics, Maxwell, waves & RF", symbol: "dot.radiowaves.left.and.right", stage: 3, lessons: [
            live("electric-field", "A charge creates an electric field", "A stationary point charge produces a radial electric field. The sign selects inward or outward direction; magnitude decreases with distance squared.", "E = q/(4πε₀r²) r̂", "Change charge and probe distance in the vacuum point-charge bench.", "Double the probe distance and predict the field's magnitude before checking it.", "One stationary ideal point charge in vacuum, away from r = 0; no materials, multiple-charge solver or time-varying fields.", .fields),
            live("potential", "Potential describes energy per charge", "For a point charge, signed potential scales as 1/r relative to infinity. The electric field points toward decreasing potential.", "V(r) = q/(4πε₀r) · E = −∇V", "Compare potential and field at different distances from the same point charge.", "Explain why doubling distance changes field and potential by different factors.", "Point-charge electrostatics in vacuum; reference is infinity and the singular charge location is excluded.", .fields),
            interactive("maxwell", "Maxwell connects electricity & magnetism", "Charge and current source fields. Changing magnetic flux induces electric circulation; changing electric fields contribute to magnetic circulation. Together these relations support waves.", "∇×E = −∂B/∂t · ∇×H = J + ∂D/∂t", "Change magnetic flux to inspect Faraday induction, then compare vacuum plane-wave E, B, energy density and Poynting flux.", "Explain when a lumped wire-and-node circuit approximation stops being adequate.", "Uniform prescribed coil flux obeying Faraday’s law, plus a sinusoidal traveling plane wave in vacuum obeying the plane-wave energy identities. Not a full solution of all Maxwell equations for the coil, a material-boundary model or a three-dimensional field solver."),
            interactive("rf", "Waves, transmission lines & antennas", "When propagation time matters, voltage and current vary along a connection. Impedance mismatch creates reflections; antennas exchange guided and radiated electromagnetic energy.", "Γ_L = (Z_L − Z₀)/(Z_L + Z₀) · v = 1/√(με)", "Launch a rectangular pulse on a lossless transmission line, move the time probe and change the termination to inspect reflections.", "Explain why a cable can matter electrically even when its DC resistance is small.", "Lossless line, specified characteristic impedance/propagation speed and matched source. First incident/reflected pulse construction; no lossy dispersion, repeated unmatched-source reflections or antenna radiation solver.")
        ], prerequisites: ["foundations", "dynamics"]),

        .init(id: "communications", title: "Put information on a wave", subtitle: "Modulation, noise, coding & networks", symbol: "antenna.radiowaves.left.and.right", stage: 3, lessons: [
            live("am", "Amplitude modulation creates sidebands", "A sinusoidal message changes a carrier's amplitude. Ideal multiplication produces spectral components at the carrier plus and minus message frequency.", "s(t) = A_c[1 + m cos(2πf_mt)]cos(2πf_ct)", "Change carrier frequency, message frequency and modulation index; inspect the AM waveform.", "Explain what fails in simple envelope detection when the modulation index exceeds one.", "Ideal single-tone double-sideband AM with carrier; no channel noise, RF circuit, antenna or demodulator implementation.", .communications),
            interactive("digital-comms", "Digital modulation & detection", "Digital symbols choose waveforms to represent bits. Detection balances symbol spacing, bandwidth and noise; a constellation is a geometric description of those choices.", "BPSK: s_b(t) = ±A cos(2πf_ct)", "Transmit seeded bits using coherent BPSK, change Eb/N0, and compare noisy decision samples with observed and theoretical bit errors.", "Explain why more bits per symbol can require higher signal-to-noise ratio.", "Normalized coherent BPSK under independent Gaussian decision noise and ideal synchronization. Finite observed BER is random-sample evidence, not an exact theoretical probability or hardware modem model."),
            interactive("information", "Noise, information & coding", "A channel carries information under bandwidth and noise constraints. Error-correcting codes add structured redundancy rather than eliminating noise physically.", "AWGN capacity: C = B log₂(1 + S/N)", "Vary AWGN bandwidth and SNR to compute capacity, then encode four bits with Hamming(7,4), inject one bit error and correct it.", "State the assumptions behind the capacity equation before treating it as a hardware performance promise.", "Shannon capacity for a bandlimited AWGN channel and an actual single-error-correcting Hamming code. Theoretical capacity is not achieved throughput; plain Hamming does not reliably detect or correct every multiple-bit error."),
            interactive("networks", "Communication networks & protocols", "A link moves symbols; a network shares paths, addresses destinations and recovers from loss. Queues and protocol rules add delay beyond physical propagation.", "Transmission time = payload bits / bit rate", "Change packet arrival, length, link rate, propagation time, queue capacity and loss; inspect an event-driven FIFO transmission timeline.", "Separate propagation delay from transmission time and queueing delay.", "One finite-buffer FIFO link with specified independent loss and deterministic event timing. No multi-hop routing, congestion control, protocol stack or wireless physical-layer simulation.")
        ], prerequisites: ["signals", "fields", "foundations"]),

        .init(id: "power", title: "Energy at useful scale", subtitle: "AC power, machines, converters & grids", symbol: "bolt.circle", stage: 3, lessons: [
            live("ac-power", "Real, reactive & apparent power", "For sinusoidal single-phase signals, voltage-current phase controls average real power. Apparent power combines the RMS magnitudes; signed reactive power describes quadrature exchange.", "P = V_rms I_rms cos φ · Q = V_rms I_rms sin φ · S = V_rms I_rms", "Vary RMS voltage, RMS current and phase; inspect instantaneous power and the power triangle.", "Keep apparent power fixed while reducing real power by changing phase.", "Ideal sinusoidal single-phase source and prescribed current; no harmonics, network load flow or converter switching.", .power),
            live("power-factor", "Power factor changes current demand", "Power factor is average real power divided by apparent power. Under the sinusoidal model, a phase shift lowers real power delivered for the same RMS current.", "PF = P/S = cos φ for sinusoidal v and i", "Compare in-phase, leading and lagging current while keeping RMS magnitudes fixed.", "Explain why reactive current still contributes to resistive wire loss in a real system.", "Sinusoidal displacement power factor only; distorted-current true power factor and compensation-network design are outside this experiment.", .power),
            interactive("machines", "Transformers & electrical machines", "Magnetic coupling transfers energy between windings. Motors and generators convert between electrical and mechanical power, with torque, speed, losses and thermal limits.", "Ideal transformer: V₂/V₁ = N₂/N₁ · P_mech = τω", "Adjust transformer ratio and load, then relate a steady-state DC motor electrical input to speed, torque and mechanical power.", "Explain why an ideal transformer voltage ratio does not create energy.", "Lossless ideal transformer and a named steady-state DC motor equivalent with winding resistance and back EMF. No saturation, core/brush losses, induction-machine transients or finite-element magnetics."),
            interactive("converters", "Power electronics, grids & energy", "Switching converters control energy flow through repeated storage and release. Grids coordinate generation, transmission, protection and loads within operational constraints.", "Ideal continuous-conduction buck: V_out ≈ D V_in", "Change buck duty, switching frequency, inductance and load; inspect ideal CCM output/ripple, then vary resistive three-phase loads and neutral current.", "List the conditions required before applying the ideal buck conversion ratio.", "Ideal buck continuous-conduction candidate with explicit CCM validity checks, plus a balanced sinusoidal source feeding independently adjustable resistive four-wire wye loads with a solid neutral. No switching loss, DCM extension, grid load flow or protection model.")
        ], prerequisites: ["circuits", "dynamics", "fields"]),

        .init(id: "computing", title: "Logic becomes a computer", subtitle: "Architecture, firmware & embedded systems", symbol: "memorychip", stage: 3, lessons: [
            interactive("architecture", "Datapaths, instructions & memory", "A processor coordinates registers, arithmetic, memory and control. Instructions describe operations; architecture and implementation decide how those operations execute.", "Execution time = instruction count × CPI × clock period", "Step a small instruction program and watch program counter, registers, ALU results and memory change.", "Explain why doubling clock frequency does not always halve program runtime.", "A declared teaching instruction set with finite registers/memory and deterministic instruction semantics. No real ISA compatibility, cache hierarchy, pipeline timing or operating-system model."),
            interactive("embedded", "Embedded software meets physical time", "Firmware reads sensors, schedules work and drives actuators. Interrupts, peripherals and real-time deadlines connect software behavior to electrical hardware.", "Periodic deadline constraint: completion time ≤ deadline", "Quantize a sensor voltage using an ideal ADC, then change periodic interrupt timing and work duration to inspect deadline margins.", "Explain the difference between a fast average response and a guaranteed worst-case deadline.", "Separate uniform ideal ADC and deterministic periodic interrupt scheduling experiments. No analog frontend dynamics, OS jitter, serial-bus electrical behavior or guaranteed real-hardware execution time."),
            interactive("hardware-design", "Design & verify a digital system", "A hardware description specifies concurrent logic. Simulation, assertions and synthesis help check behavior, while physical implementation introduces area, delay and power tradeoffs.", "Dynamic CMOS power ≈ α C V² f", "Clock a four-state controller, inject an output-decoder fault and exhaustively check safety states; vary CMOS activity, capacitance, voltage and frequency.", "Write a safety property that catches simultaneous greens without repeating the decoder implementation.", "Fixed logical FSM with hold/advance and exhaustive no-simultaneous-greens property check, plus alpha-C-V-squared-f dynamic power. No editable HDL, FPGA synthesis, physical layout, leakage or short-circuit power model.")
        ], prerequisites: ["digital", "devices", "signals"]),

        .init(id: "practice", title: "Think and work like an engineer", subtitle: "Measurement, design, ethics & capstone", symbol: "wrench.and.screwdriver", stage: 4, lessons: [
            interactive("instrumentation", "Measurement changes the circuit", "Meters, probes and sensors load the system they observe. Calibration, bandwidth, grounding and uncertainty determine whether a reading supports a conclusion.", "Loaded divider: V_meas = Vₛ(R₂ ∥ R_in)/(R₁ + (R₂ ∥ R_in))", "Change divider resistance and probe input resistance/capacitance; compare unloaded DC, measured DC and a loaded frequency response.", "Explain why a high-input-resistance voltmeter still changes a sufficiently high-resistance circuit.", "Ideal source/resistors with a parallel R-C probe. Includes loading and bandwidth; excludes calibration/noise, inductive ground leads, protection circuits and distributed cables."),
            interactive("design", "Design starts with constraints", "An engineering design translates needs into measurable requirements. Models, prototypes and experiments narrow uncertainty; tradeoffs include cost, reliability, power, safety and manufacturability.", "Efficiency η = useful output energy / input energy", "Compare three loaded divider candidates against adjustable voltage-error, current and power constraints across independent tolerance corners.", "Write a requirement with a measurable acceptance condition rather than a preferred component.", "Eight bounded tolerance corners with exact DC resistor equations. Bounds are not confidence intervals; power rating comparisons do not include thermal derating or reliability certification."),
            interactive("ethics", "Engineering decisions affect people", "Engineers communicate evidence and limits, identify affected people and consider safety, accessibility, environmental impact and professional responsibility throughout design.", "A claim needs evidence, assumptions and an explicit uncertainty bound.", "Choose among evidence, fault-response and privacy/accessibility cases, review the consequences of proposed actions, and save a decision record.", "Describe what should be disclosed when a simulation omits a failure mode relevant to a design decision.", "Authored hypothetical engineering cases with qualitative reasoning. No numerical moral score, legal advice or certification; professional judgment and review remain necessary."),
            interactive("capstone", "Capstone: build, test & explain", "A capstone integrates circuits, computing and a chosen specialty into a designed system. Success requires requirements, independent verification, documentation and physical experimental evidence.", "Requirement → model → prototype → test → revision", "Configure a temperature sensor, ADC, sampled controller, heater and thermal plant; test requirements and export a reproducible model/results report.", "Choose independent tests that could disprove your design's central performance claim.", "Lumped constant-C/h thermal plant, exact held-input evolution, uniform ADC and static sensor bias, ideal switch/resistor, sampled hysteresis. No physical prototype or safety/failure certification is implied.")
        ], prerequisites: ["circuits", "digital", "devices", "signals", "control", "computing"])
    ]

    static var lessonCount: Int { modules.reduce(0) { $0 + $1.lessons.count } }
    static var implementedCount: Int { modules.reduce(0) { $0 + $1.implementedCount } }
    static var plannedCount: Int { lessonCount - implementedCount }

    private static func live(_ id: String, _ title: String, _ concept: String, _ equation: String, _ experiment: String, _ challenge: String, _ limit: String, _ destination: LabDestination) -> CourseLesson {
        .init(id: id, title: title, concept: concept, equation: equation, experiment: experiment, challenge: challenge, modelLimit: limit, destination: destination)
    }

    private static func interactive(_ id: String, _ title: String, _ concept: String, _ equation: String, _ experiment: String, _ challenge: String, _ limit: String) -> CourseLesson {
        .init(id: id, title: title, concept: concept, equation: equation, experiment: experiment, challenge: challenge, modelLimit: limit, destination: nil)
    }
}
